});
export function characterTuning(id:unknown,mapId:MapId,landOverride?:CharacterMultipliers){
 const profile=resolveCharacter(id),land=resolveMap(mapId).vehicle==='kart',base=MAP_BASELINES[land?'coast':'waterpark'];
