  return RACE_MUSIC[Math.floor(random() * RACE_MUSIC.length)];

export const racingSpeed = (r: Combatant, max: number) => clamp(r.speed, 0, max) * (r.boost > 0 ? RULES.boostFactor : 1) * (slowTime(r) > 0 ? slowMultiplier(r) : 1);
/** Experimental attack sources never overwrite legacy collision/terrain slow. */
export function slowTime(r:Combatant){return Math.max(r.slow,r.itemStacking?r.pulseSlow??0:0,r.itemStacking?r.upgradedPulseSlow??0:0);}
export function slowMultiplier(r:Combatant){return r.itemStacking&&(r.upgradedPulseSlow??0)>0?.45:RULES.slowFactor;}
